import { describe, it, expect, vi, beforeEach } from 'vitest';
import { buildServer } from '../server';

const prismaMock = vi.hoisted(() => ({
  endpoint: { create: vi.fn(), findUnique: vi.fn(), update: vi.fn() },
  delivery: { findMany: vi.fn(), findUnique: vi.fn(), findUniqueOrThrow: vi.fn(), update: vi.fn() },
}));
const queueMock = vi.hoisted(() => ({ add: vi.fn() }));

vi.mock('@tallyhook/shared', async () => {
  const schemas = await vi.importActual<typeof import('@tallyhook/shared/src/schemas')>(
    '@tallyhook/shared/src/schemas',
  );
  return { ...schemas, prisma: prismaMock, logger: false };
});

vi.mock('../queue', () => ({ deliveryQueue: queueMock, redis: {} }));

describe('POST /v1/dead-letters/:id/requeue', () => {
  beforeEach(() => vi.clearAllMocks());

  it('404s for an unknown delivery', async () => {
    prismaMock.delivery.findUnique.mockResolvedValue(null);
    const res = await buildServer().inject({ method: 'POST', url: '/v1/dead-letters/nope/requeue' });
    expect(res.statusCode).toBe(404);
    expect(res.json()).toEqual({ error: 'not_found' });
    expect(queueMock.add).not.toHaveBeenCalled();
  });

  it('409s when the delivery is not dead', async () => {
    prismaMock.delivery.findUnique.mockResolvedValue({ id: 'dl_1', status: 'FAILED' });
    const res = await buildServer().inject({ method: 'POST', url: '/v1/dead-letters/dl_1/requeue' });
    expect(res.statusCode).toBe(409);
  });
});

